import sys
from collections import Counter

n = int(sys.stdin.readline().strip())
s = sys.stdin.readline().strip()

count = Counter(s)
target = n // 4

if any(count[c] > target for c in 'ACGT'):
    print('===')
else:
    to_add = {c: target - count[c] for c in 'ACGT'}
    result = []
    for c in s:
        if c != '?':
            result.append(c)
        else:
            for nucleotide in 'ACGT':
                if to_add[nucleotide] > 0:
                    result.append(nucleotide)
                    to_add[nucleotide] -= 1
                    break
    print(''.join(result))
